class AlgebraicStructure:
    """Represents a binary operation on a finite set."""

    def __init__(self, operation_table):
        """
        operation_table[i][j] = result of i * j
        """
        self.table = np.array(operation_table)
        self.size = len(operation_table)
        self.elements = list(range(self.size))

    def __hash__(self):
        return hash(self.table.tobytes())

    def __eq__(self, other):
        return np.array_equal(self.table, other.table)

    def operate(self, a, b):
        return self.table[a][b]

    def is_associative(self):
        """Check if (a*b)*c = a*(b*c) for all elements."""
        for a, b, c in itertools.product(self.elements, repeat=3):
            ab_c = self.operate(self.operate(a, b), c)
            a_bc = self.operate(a, self.operate(b, c))
            if ab_c != a_bc:
                return False
        return True

    def is_commutative(self):
        """Check if a*b = b*a for all elements."""
        for a, b in itertools.product(self.elements, repeat=2):
            if self.operate(a, b) != self.operate(b, a):
                return False
        return True

    def find_identity(self):
        """Find identity element if it exists."""
        for e in self.elements:
            is_identity = True
            for a in self.elements:
                if self.operate(e, a) != a or self.operate(a, e) != a:
                    is_identity = False
                    break
            if is_identity:
                return e
        return None

    def find_inverses(self, identity):
        """Find inverse of each element with respect to given identity."""
        inverses = {}
        for a in self.elements:
            for b in self.elements:
                if self.operate(a, b) == identity and self.operate(b, a) == identity:
                    inverses[a] = b
                    break
        return inverses if len(inverses) == self.size else None

    def is_group(self):
        """Check if structure forms a group."""
        if not self.is_associative():
            return False, "Not associative"

        identity = self.find_identity()
        if identity is None:
            return False, "No identity"

        inverses = self.find_inverses(identity)
        if inverses is None:
            return False, "Not all elements have inverses"

        return True, {"identity": identity, "inverses": inverses}

    def is_closed(self):
        """Check if all operations stay within the set."""
        return np.all((self.table >= 0) & (self.table < self.size))

    def get_canonical_form(self):
        """Get canonical form by finding lexicographically smallest isomorph."""
        # Try all permutations of elements and find smallest table
        min_table = self.table.copy()

        for perm in itertools.permutations(self.elements):
